import createGhostscript from './vendor/ghostscript/gs.mjs';
self.onmessage=async({data:{input}})=>{try{const gs=await createGhostscript({noInitialRun:true,locateFile:name=>new URL('./vendor/ghostscript/'+name,import.meta.url).href,print:()=>{},printErr:()=>{}});const icc=await fetch(new URL('./vendor/ghostscript/srgb.icc',import.meta.url)).then(r=>r.arrayBuffer());gs.FS.writeFile('/input.pdf',new Uint8Array(input));gs.FS.writeFile('/srgb.icc',new Uint8Array(icc));
const definition=`/ICCProfile (/srgb.icc) def\n[/_objdef {icc_PDFA} /type /stream /OBJ pdfmark\n[{icc_PDFA} << /N 3 >> /PUT pdfmark\n[{icc_PDFA} ICCProfile (r) file /PUT pdfmark\n[/_objdef {OutputIntent_PDFA} /type /dict /OBJ pdfmark\n[{OutputIntent_PDFA} << /Type /OutputIntent /S /GTS_PDFA1 /DestOutputProfile {icc_PDFA} /OutputConditionIdentifier (sRGB) /Info (sRGB IEC61966-2.1) >> /PUT pdfmark\n[{Catalog} << /OutputIntents [ {OutputIntent_PDFA} ] >> /PUT pdfmark\n`;
gs.FS.writeFile('/PDFA.ps',definition);try{gs.callMain(['-q','-dBATCH','-dNOPAUSE','-dSAFER','--permit-file-read=/srgb.icc','-dPDFA=2','-sDEVICE=pdfwrite','-sColorConversionStrategy=RGB','-sOutputICCProfile=/srgb.icc','-dPDFACompatibilityPolicy=1','-sOutputFile=/output.pdf','/PDFA.ps','/input.pdf']);}catch(e){if(e.status!==0)throw new Error('归档转换失败，文件可能含不受支持的特性');}const output=gs.FS.readFile('/output.pdf');self.postMessage({output:output.buffer},[output.buffer]);}catch(e){self.postMessage({error:e.message||'PDF/A 引擎加载或转换失败'});}};
